const wc = $('When Called').first().json;
function pStr(v){ return (v == null) ? '' : String(v); }
let refIds = [];
try { const raw = wc.reference_file_ids_json; const p = (typeof raw === 'string') ? JSON.parse(raw || '[]') : (Array.isArray(raw) ? raw : []); if (Array.isArray(p)) refIds = p.map(function(x){ return String(x); }).filter(Boolean); } catch (e) { refIds = []; }
const prompt = pStr(wc.prompt).trim();
let count = Number(wc.count); if (!count || isNaN(count) || count < 1) count = 1;
const aspect = pStr(wc.aspect_ratio).trim();
const size = pStr(wc.size).trim();
const tool_input = { prompt: prompt, reference_file_ids: refIds, count: count };
if (aspect) tool_input.aspect_ratio = aspect;
if (size) tool_input.size = size;
// clickup_task_id: agent-copied from its message (the ONLY task-attribution channel on the MCP path — Block 5.1). Trim; permissive length cap to drop obvious junk; empty/implausible -> '' (handled + WARNed downstream).
let taskId = pStr(wc.clickup_task_id).trim();
if (taskId.length > 64) taskId = '';
return [{ json: {
  tool_input_json: JSON.stringify(tool_input),
  ref_ids: refIds,
  ref_ids_json: JSON.stringify(refIds),
  has_refs: refIds.length > 0,
  clickup_task_id: taskId
} }];

const items = $input.all();
const rows = items.map(function(i){ return i.json; }).filter(function(r){ return r && r.file_id; });
const dbError = items.some(function(i){ return i.json && i.json.error; });
const p = $('Parse Tool Input').first().json;
const file_map = rows.map(function(r){ return { file_id: r.file_id, url: r.url, source_ref: r.source_ref, mime: r.mime }; });
const pre_warnings = [];
if (dbError) pre_warnings.push({ source: 'image-mcp/reference-lookup-failed', err: 'agent_input_file_map lookup failed; generating without reference images', severity: 'WARN' });
// ADR-057 follow-up: attribute the per-image cost row to the triggering task using the id the agent copied into clickup_task_id (the only channel — Block 5.1). Empty => the model omitted it; the image cost falls back to a NULL task_id (un-attributed, as before) and we WARN so the silent degradation is visible (CLAUDE.md reliability mandate).
const clickup_task_id = (p.clickup_task_id || '').toString();
if (!clickup_task_id) pre_warnings.push({ source: 'image-mcp/missing-task-id', err: 'generate_image called without clickup_task_id; image cost logged with NULL task id (not attributed to the task field/footer). The agent did not copy the task id from its message.', severity: 'WARN' });
return [{ json: {
  tool_input_json: p.tool_input_json,
  file_map_json: JSON.stringify(file_map),
  impact: 'Średni',
  concurrency_cap: 5,
  clickup_task_id: clickup_task_id,
  triggered_by: 'image_mcp',
  invocation_type: 'explicit',
  caller_user_id: '',
  process_type: '',
  pre_warnings_json: JSON.stringify(pre_warnings),
  requested_refs: (Array.isArray(p.ref_ids) ? p.ref_ids.length : 0),
  resolved_refs: file_map.length
} }];

const h = $json || {};
let pre = []; try { pre = JSON.parse(($('Build Handler Inputs').first().json.pre_warnings_json) || '[]'); } catch (e) {}
const hw = Array.isArray(h.warnings) ? h.warnings : [];
const warnings = pre.concat(hw);
return [{ json: {
  status: h.status || 'failed',
  file_ids: Array.isArray(h.file_ids) ? h.file_ids : [],
  message: h.message || 'Image tool returned no message.',
  count_uploaded: (h.count_uploaded != null) ? h.count_uploaded : 0,
  count_failed: (h.count_failed != null) ? h.count_failed : 0,
  warnings: warnings
} }];

const e = $json || {};
const err = (e.error && (e.error.message || e.error)) || e.message || 'image tool handler threw';
let pre = []; try { pre = JSON.parse(($('Build Handler Inputs').first().json.pre_warnings_json) || '[]'); } catch (ex) {}
const warnings = pre.concat([{ source: 'image-mcp/handler-threw', err: String(err).slice(0, 400), severity: 'CRITICAL' }]);
return [{ json: {
  status: 'failed',
  file_ids: [],
  message: 'Image generation failed (internal error). Proceed without the image and tell the user it could not be generated.',
  count_uploaded: 0,
  count_failed: 0,
  warnings: warnings
} }];

const o = $json;
const warnings = Array.isArray(o.warnings) ? o.warnings : [];
let do_alert = false, sev = 'WARN', msg = '', det = '';
if (warnings.length > 0){
  do_alert = true;
  const hasCrit = warnings.some(function(w){ return w.severity === 'CRITICAL'; });
  sev = hasCrit ? 'CRITICAL' : 'WARN';
  msg = 'Image MCP generate_image zakonczone z ostrzezeniami (' + warnings.length + ') [status: ' + (o.status || '?') + ']';
  det = warnings.map(function(w){ return (w.source || '') + ': ' + (w.err || ''); }).join(' | ').slice(0, 1500);
}
return [{ json: Object.assign({}, o, { do_alert: do_alert, _sev: sev, _msg: msg, _details: det }) }];
